sys_script_include.script:
var MyAssetRequestUpdater = Class.create();
MyAssetRequestUpdater.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    updateFieldValue: function() {
        try {
            // 增强参数获取
            var sysId = this.getParameter('sysparm_sys_id');
            var table = this.getParameter('sysparm_table');
            var field = this.getParameter('sysparm_field');
            var value = this.getParameter('sysparm_value');

            // 验证参数
            if (!sysId || !table || !field || !value) {
                gs.error("[MyAssetRequestUpdater] 缺少必要参数");
                return "缺少必要参数";
            }

            // 使用GlideRecordSecure增强安全性
            var gr = new GlideRecordSecure(table);
            if (!gr.isValid()) {
                gs.error("[MyAssetRequestUpdater] 无效的表名: " + table);
                return "无效的表名";
            }

            if (!gr.get(sysId)) {
                gs.error("[MyAssetRequestUpdater] 记录不存在或无权访问: " + sysId);
                return "记录不存在或无权访问";
            }

            if (!gr.isValidField(field)) {
                gs.error("[MyAssetRequestUpdater] 无效的字段名: " + field);
                return "无效的字段名";
            }

            // 执行更新
            gr.setValue(field, value);
            gr.setValue('my_notes', '状态更新为: ' + value + ' (操作人: ' + gs.getUserDisplayName() + ')');

            var updateResult = gr.update();

            if (updateResult) {
                return "success";
            } else {
                var error = gr.getError();
                gs.error("[MyAssetRequestUpdater] 更新失败: " + (error || "未知原因"));
                return error || "更新失败: 未知原因";
            }
        } catch (e) {
            gs.error("[MyAssetRequestUpdater] 系统异常: " + e.getMessage());
            return "系统异常: " + e.getMessage();
        }
    },

    type: 'MyAssetRequestUpdater'
});
